class Solution {
public:
    int majorityElement(vector<int>& nums) {
        int cand = nums[0], cnt = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            if (cnt == 0) cand = nums[i];
            if (nums[i] == cand) cnt++;
            else cnt--;
        }
        return cand;
    }
};
